        Button add = new Button(this); add.setText("＋ 添加"); add.setTextColor(Color.rgb(225,196,255)); add.setTextSize(14); add.setAllCaps(false); add.setBackgroundColor(Color.TRANSPARENT); action.addView(add,new LinearLayout.LayoutParams(dp(80),dp(48))); add.setOnClickListener(v->pickAudio()); Button online = new Button(this); online.setText("在线"); online.setTextColor(Color.rgb(225,196,255)); online.setTextSize(14); online.setAllCaps(false); online.setBackgroundColor(Color.TRANSPARENT); action.addView(online,new LinearLayout.LayoutParams(dp(62),dp(48))); online.setOnClickListener(v->onlineSearch()); Button favorites = new Button(this); favorites.setText("收藏"); favorites.setTextColor(Color.rgb(225,196,255)); favorites.setTextSize(14); favorites.setAllCaps(false); favorites.setBackgroundColor(Color.TRANSPARENT); action.addView(favorites,new LinearLayout.LayoutParams(dp(62),dp(48))); favorites.setOnClickListener(v->showFavorites()); Button playlists = new Button(this); playlists.setText("歌单"); playlists.setTextColor(Color.rgb(225,196,255)); playlists.setTextSize(14); playlists.setAllCaps(false); playlists.setBackgroundColor(Color.TRANSPARENT); action.addView(playlists,new LinearLayout.LayoutParams(dp(62),dp(48))); playlists.setOnClickListener(v->showPlaylists()); Button queue = new Button(this); queue.setText("队列"); queue.setTextColor(Color.rgb(225,196,255)); queue.setTextSize(14); queue.setAllCaps(false); queue.setBackgroundColor(Color.TRANSPARENT); action.addView(queue,new LinearLayout.LayoutParams(dp(62),dp(48))); queue.setOnClickListener(v->showQueue()); Button artists = new Button(this); artists.setText("更多"); artists.setTextColor(Color.rgb(225,196,255)); artists.setTextSize(14); artists.setAllCaps(false); artists.setBackgroundColor(Color.TRANSPARENT); action.addView(artists,new LinearLayout.LayoutParams(dp(62),dp(48))); artists.setOnClickListener(v->showMore()); root.addView(action,new LinearLayout.LayoutParams(-1,dp(52)));
        TextView heading = text("本地歌曲  ·  "+names.size(),18,Color.WHITE); heading.setTypeface(null,1); heading.setPadding(0,dp(18),0,dp(8)); root.addView(heading,new LinearLayout.LayoutParams(-1,dp(52)));
        ListView list = new ListView(this); list.setDivider(null); list.setPadding(0,0,0,dp(6)); list.setBackgroundColor(Color.TRANSPARENT);
        adapter = new ArrayAdapter<String>(this,android.R.layout.simple_list_item_1,names){ @Override public View getView(int pos,View convert,ViewGroup parent){ TextView v=(TextView)super.getView(pos,convert,parent); v.setTextColor(Color.rgb(236,230,240)); v.setTextSize(16); v.setGravity(Gravity.CENTER_VERTICAL); v.setPadding(dp(16),0,dp(10),0); v.setBackground(bg(Color.rgb(28,23,35),16)); LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(54)); lp.setMargins(0,dp(4),0,dp(4)); v.setLayoutParams(lp); return v; }};
        list.setAdapter(adapter); search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){} public void onTextChanged(CharSequence s,int st,int b,int c){adapter.getFilter().filter(s);} public void afterTextChanged(Editable e){}}); root.addView(list,new LinearLayout.LayoutParams(-1,0,1)); list.setOnItemClickListener((p,v,pos,id)->{String n=adapter.getItem(pos); playIndex(names.indexOf(n));}); list.setOnItemLongClickListener((p,v,pos,id)->{String n=adapter.getItem(pos); removeTrack(names.indexOf(n)); return true;});
